MAX_FAILED_ATTEMPTS = 5
LOCKOUT_SECONDS = 3600


def attempt_key(username: str) -> str:
    return f"attempt:{username}"


def lockout_key(username: str) -> str:
    return f"lockout:{username}"


def is_locked(username: str) -> bool:
    try:
        return redis_client.exists(lockout_key(username)) == 1
    except redis.RedisError:
        app.logger.exception("Redis unavailable during lockout check")
        # Decide your policy. For this MVP example: log and continue without lockout.
        return False


def record_failed_login(username: str) -> None:
    try:
        pipe = redis_client.pipeline()
        pipe.incr(attempt_key(username))
        pipe.expire(attempt_key(username), LOCKOUT_SECONDS)
        count = pipe.execute()[0]

        if count >= MAX_FAILED_ATTEMPTS:
            redis_client.setex(lockout_key(username), LOCKOUT_SECONDS, "1")
            redis_client.delete(attempt_key(username))
    except redis.RedisError:
        app.logger.exception("Redis unavailable while recording failed login")


def clear_failed_logins(username: str) -> None:
    try:
        redis_client.delete(attempt_key(username), lockout_key(username))
    except redis.RedisError:
        app.logger.exception("Redis unavailable while clearing failed login state")
